permits = [("P-101", "FCC-2", "화기", 9, 12), ("P-102", "TK-7", "밀폐공간", 10, 11), ("P-103", "FCC-2", "일반", 13, 15)]
gas = {("FCC-2", 9): 0, ("FCC-2", 10): 4, ("FCC-2", 11): 12, ("TK-7", 10): 0}
LIMIT = 10  # LEL %
for pid, area, kind, s, e in permits:
    for h in range(s, e):
        v = gas.get((area, h))
        if kind == "화기" and v is not None and v >= LIMIT:
            print(f"{pid} {area} {h}시 LEL {v}% -> 화기작업 중지 알림")
# 출력: P-101 FCC-2 11시 LEL 12% -> 화기작업 중지 알림
